def transform(grid):
    from collections import Counter
    H = len(grid); W = len(grid[0])
    cnt = Counter(grid[r][c] for r in range(H) for c in range(W))
    bg = cnt.most_common(1)[0][0]
    rest = [c for c, _ in cnt.most_common() if c != bg]
    rest.sort(key=lambda c: -cnt[c])
    divider = rest[0] if rest else None
    marker = rest[1] if len(rest) > 1 else None
    # vertical runs (>=3) of divider color
    div = set()
    for c in range(W):
        r = 0
        while r < H:
            if grid[r][c] == divider:
                r2 = r
                while r2 < H and grid[r2][c] == divider:
                    r2 += 1
                if r2 - r >= 3:
                    for k in range(r, r2):
                        div.add((k, c))
                r = r2
            else:
                r += 1
    out = [row[:] for row in grid]
    rows_with_div = sorted({r for r, c in div})
    i = 0
    while i < len(rows_with_div):
        j = i
        while j + 1 < len(rows_with_div) and rows_with_div[j + 1] == rows_with_div[j] + 1:
            j += 1
        rws = rows_with_div[i:j + 1]
        cols = [c for r in rws for c in range(W) if (r, c) in div]
        d = cols[0]
        has_marker = marker is not None and any(grid[r][c] == marker for r in rws for c in range(W))
        if has_marker:
            for r in rws:
                mcols = [c for c in range(W) if grid[r][c] == marker]
                if not mcols:
                    continue
                lo, hi = min(mcols), max(mcols)
                if d < lo:
                    a, b = d + 1, hi
                else:
                    a, b = lo, d - 1
                for c in range(a, b + 1):
                    if grid[r][c] == marker:
                        out[r][c] = 4
                    elif grid[r][c] == bg:
                        out[r][c] = marker
                for c in mcols:
                    out[r][c] = 4
        else:
            skip = rws[(len(rws) - 1) // 2]
            left = d < W / 2
            for r in rws:
                if r == skip:
                    continue
                rng = range(d + 1, W) if left else range(0, d)
                for c in rng:
                    if grid[r][c] == bg:
                        out[r][c] = marker
        i = j + 1
    return out
