The extra rule from demo 2: the region without markers fills whole rows (except its divider column) on rows aligned by index with marker rows of the other region. Verified against both demos.

```python
def transform(grid):
    from collections import Counter
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    rest = [c for c, _ in cnt.most_common() if c != bg]
    rest.sort(key=lambda c: -cnt[c])
    divider = rest[0] if rest else None
    marker = rest[1] if len(rest) > 1 else None
    # vertical runs (>=3) of divider color define regions
    regions = []
    for c in range(W):
        r = 0
        while r < H:
            if grid[r][c] == divider:
                r2 = r
                while r2 < H and grid[r2][c] == divider:
                    r2 += 1
                if r2 - r >= 3:
                    regions.append({'rows': list(range(r, r2)), 'col': c})
                r = r2
            else:
                r += 1
    for reg in regions:
        reg['has_marker'] = marker is not None and any(
            grid[r][c] == marker for r in reg['rows'] for c in range(W))
    out = [row[:] for row in grid]
    marker_regions = [g for g in regions if g['has_marker']]
    other_regions = [g for g in regions if not g['has_marker']]
    # marker regions: fill between divider and marker
    for reg in marker_regions:
        d = reg['col']
        for r in reg['rows']:
            mcols = [c for c in range(W) if grid[r][c] == marker]
            if not mcols:
                continue
            if d < min(mcols):
                lo, hi = d + 1, W - 1
            else:
                lo, hi = 0, d - 1
            for c in range(lo, hi + 1):
                if grid[r][c] == bg:
                    out[r][c] = marker
            for c in mcols:
                out[r][c] = 4
    # no-marker regions: fill aligned rows fully (except divider col)
    for reg in other_regions:
        d = reg['col']
        for mreg in marker_regions:
            for i, r in enumerate(reg['rows']):
                if i < len(mreg['rows']) and any(
                        grid[mreg['rows'][i]][c] == marker for c in range(W)):
                    for c in range(W):
                        if c != d and grid[r][c] == bg:
                            out[r][c] = marker
    return out
