My previous marker-row fill extended past the marker; per demo 1 row 13 (col 0 stays 8), the fill in marker rows is strictly between the divider and the marker. Fixing that and cleaning up color/region detection:

```python
def transform(grid):
    from collections import Counter
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    nonbg = [c for c in cnt if c != bg]
    # divider: color forming a vertical run of length >= 3
    def has_vruns(col):
        for c in range(W):
            run = 0
            for r in range(H):
                if grid[r][c] == col:
                    run += 1
                    if run >= 3:
                        return True
                else:
                    run = 0
        return False
    divs = [c for c in nonbg if has_vruns(c)]
    divs.sort(key=lambda c: -cnt[c])
    divider = divs[0] if divs else nonbg[0]
    marker = next((c for c in nonbg if c != divider), None)

    # vertical runs of divider
    regions = []
    for c in range(W):
        r = 0
        while r < H:
            if grid[r][c] == divider:
                r2 = r
                while r2 < H and grid[r2][c] == divider:
                    r2 += 1
                if r2 - r >= 3:
                    regions.append({'rows': list(range(r, r2)), 'col': c})
                r = r2
            else:
                r += 1
    for reg in regions:
        reg['marker_rows'] = [r for r in reg['rows']
                              if marker is not None and any(grid[r][c] == marker for c in range(W))]
    out = [row[:] for row in grid]
    mregs = [g for g in regions if g['marker_rows']]
    oregs = [g for g in regions if not g['marker_rows']]

    # marker regions: fill strictly between divider and nearest marker; marker -> 4
    for reg in mregs:
        d = reg['col']
        for r in reg['marker_rows']:
            mcols = [c for c in range(W) if grid[r][c] == marker]
            near = min(mcols, key=lambda c: abs(c - d))
            lo, hi = (d + 1, near - 1) if d < near else (near + 1, d - 1)
            for c in range(max(lo, 0), min(hi, W - 1) + 1):
                if grid[r][c] == bg:
                    out[r][c] = marker
            for c in mcols:
                out[r][c] = 4

    # no-marker regions: fill rows aligned (by index) with marker rows of a marker region
    for reg in oregs:
        d = reg['col']
        for mreg in mregs:
            for i, r in enumerate(reg['rows']):
                if i < len(mreg['rows']) and mreg['rows'][i] in mreg['marker_rows']:
                    for c in range(W):
                        if c != d and grid[r][c] == bg:
                            out[r][c] = marker
    return out
```

